// The three premade maps (hand written with fillRect) + the static entities that belong to them
// (stores, sell points, objective buildings, level gates, decoration). Trees are generated by code.
//
// Coordinates: tile positions are multiplied by tileSize (16) to get world pixels.

#include <random>
#include <cmath>
#include <algorithm>

#include "levels.h"
#include "scene.h"
#include "globals.h"

static const float T = static_cast<float>(tileSize);

static std::shared_ptr<sellPoint> addSell(GameScene& s, int level, const std::string& name, int tx, int ty, int tw, int th, sf::Color col)
{
	auto sp = std::make_shared<sellPoint>(name, sf::FloatRect(tx * T, ty * T, tw * T, th * T), col);
	s.addEntityToLevel(level, sp);
	return sp;
}

static void addBushes(GameScene& s, int level, std::mt19937& rng, int count, int x0, int y0, int x1, int y1)
{
	std::uniform_int_distribution<int> dx(x0, x1), dy(y0, y1);
	tileMap& m = s.levels[level].map;
	for (int i = 0; i < count; i++){
		int tx = dx(rng), ty = dy(rng);
		unsigned char t = m.getTileAt(tx, ty);
		if (t != T_GRASS && t != T_SNOW) continue;
		s.addEntityToLevel(level, std::make_shared<bush>(tx * T + 8.0f, ty * T + 14.0f));
	}
}

int treeTargetForLevel(int level)
{
	static const int targets[LEVEL_COUNT] = {230, 170, 150};
	return targets[level];
}

// can a new tree grow on this tile? (also used for the "Generate New Tree" box in the gameplay flowchart)
bool isTreeSpot(GameScene& scene, int level, int tx, int ty)
{
	tileMap& m = scene.levels[level].map;
	if (tx < 3 || ty < 3 || tx >= m.width() - 3 || ty >= m.height() - 3) return false;
	unsigned char t = m.getTileAt(tx, ty);
	if (t != T_GRASS && t != T_SNOW) return false;
	sf::Vector2f p(tx * T + 8.0f, ty * T + 14.0f);
	sf::Vector2f sp = scene.levels[level].spawn;
	if (std::fabs(sp.x - p.x) < 5 * T && std::fabs(sp.y - p.y) < 5 * T) return false; // keep the spawn clear
	for (auto& e : scene.levels[level].entities){
		if (e->isDead()) continue;
		int c = e->getClass();
		if (c == EC_ITEM || c == EC_PLAYER || c == EC_WORKER) continue;
		sf::Vector2f q = e->getPosition();
		if (c == EC_TREE || c == EC_STUMP || c == EC_BUSH){
			if (std::fabs(q.x - p.x) < 12.0f && std::fabs(q.y - p.y) < 10.0f) return false;
		}else if (e->isSolid()){
			sf::FloatRect b = e->getHitbox();
			b.left -= 14.0f; b.top -= 10.0f; b.width += 28.0f; b.height += 24.0f;
			if (b.contains(p)) return false;
		}else if (c == EC_SELL || c == EC_GATE){
			if (std::fabs(q.x - p.x) < 90.0f && std::fabs(q.y - p.y) < 70.0f) return false;
		}
	}
	return true;
}

static void generateTrees(GameScene& scene, int level, std::mt19937& rng)
{
	tileMap& m = scene.levels[level].map;
	std::uniform_int_distribution<int> dx(3, m.width() - 4), dy(3, m.height() - 4);
	int target = treeTargetForLevel(level);
	int placed = 0, attempts = 0;
	while (placed < target && attempts < target * 40){
		attempts++;
		int tx = dx(rng), ty = dy(rng);
		if (!isTreeSpot(scene, level, tx, ty)) continue;
		scene.spawnTreeAt(level, tx, ty);
		placed++;
	}
}

// =====================================================================================================================
//  Level 0 - Cedar Valley (the start: wooded area with a town nearby, a river, the port and the train station)
// =====================================================================================================================
static void buildCedarValley(GameScene& s, bool trees)
{
	GameScene::levelState& L = s.levels[0];
	L.name = "Cedar Valley";
	tileMap& m = L.map;
	m.create(80, 50, T_GRASS);
	// boundaries: hills (the player can not leave the area)
	m.fillRect(0, 0, 80, 2, T_HILL); m.fillRect(0, 48, 80, 2, T_HILL);
	m.fillRect(0, 0, 2, 50, T_HILL); m.fillRect(78, 0, 2, 50, T_HILL);
	m.fillRect(28, 3, 7, 5, T_HILL);                 // a rocky outcrop
	m.fillRect(4, 36, 5, 4, T_HILL);
	// river flowing south (logs dropped in drift to the River Dock)
	m.fillRect(14, 2, 2, 44, T_WATER);
	m.setFlow(14, 2, 2, 44, 0, 1);
	// the town (sand) + road (brick path) crossing the river on a bridge
	m.fillRect(42, 19, 22, 16, T_SAND);
	m.fillRect(2, 26, 74, 2, T_PATH);
	m.fillRect(14, 26, 2, 2, T_BRIDGE);
	// port lake (east) + shore
	m.fillRect(62, 29, 8, 14, T_SAND);
	m.fillRect(70, 29, 8, 18, T_WATER);
	// train station yard
	m.fillRect(58, 7, 13, 10, T_SAND);
	// a pond
	m.fillRect(26, 36, 3, 3, T_WATER);
	
	L.spawn = sf::Vector2f(34 * T, 24 * T + 8.0f);

	// --- town buildings: General Store (axes + truck) and Labour Office (hire workers)
	s.addEntityToLevel(0, std::make_shared<storeBuilding>(STORE_GENERAL, "General Store", sf::Vector2f(48 * T + 8.0f, 25 * T), sf::Vector2f(64.0f, 52.0f)));
	s.addEntityToLevel(0, std::make_shared<storeBuilding>(STORE_LABOUR, "Labour Office", sf::Vector2f(57 * T + 8.0f, 25 * T), sf::Vector2f(64.0f, 52.0f)));

	// --- sell points (private companies in the local town + one on the river)
	auto sawmill = addSell(s, 0, "Cedar Sawmill", 44, 29, 8, 5, sf::Color(0xcc, 0x41, 0x25));
	for (int t = ITEM_LOG_SPRUCE; t <= ITEM_LOG_FROST; t++) sawmill->setPrice(static_cast<itemType>(t), itemBasePrice(static_cast<itemType>(t)));
	auto firewood = addSell(s, 0, "Firewood Merchant", 54, 29, 8, 5, sf::Color(0xe6, 0x91, 0x38));
	for (int t = ITEM_LOG_SPRUCE; t <= ITEM_LOG_FROST; t++) firewood->setPrice(static_cast<itemType>(t), itemBasePrice(static_cast<itemType>(t)) * 0.6f);
	firewood->setPrice(ITEM_CHIP, 6.0f);
	firewood->setPrice(ITEM_PLANK, 20.0f);
	auto dock = addSell(s, 0, "River Dock", 11, 44, 8, 4, sf::Color(0x3d, 0x85, 0xc6));
	for (int t = ITEM_LOG_SPRUCE; t <= ITEM_LOG_FROST; t++) dock->setPrice(static_cast<itemType>(t), itemBasePrice(static_cast<itemType>(t)) * 0.9f);

	// --- objective buildings: the port and the train station
	auto port = std::make_shared<objectiveBuilding>(0, "Port", sf::Vector2f(65 * T, 33 * T), sf::Vector2f(64.0f, 48.0f));
	port->required[ITEM_LOG_SPRUCE] = 20; port->required[ITEM_LOG_PINE] = 10; port->required[ITEM_PLANK] = 8;
	s.addEntityToLevel(0, port);
	auto station = std::make_shared<objectiveBuilding>(1, "Train Station", sf::Vector2f(64 * T, 12 * T), sf::Vector2f(80.0f, 56.0f));
	station->required[ITEM_PLANK] = 20; station->required[ITEM_LOG_OAK] = 12; station->required[ITEM_LOG_FROST] = 8;
	s.addEntityToLevel(0, station);
	// --- level gates: invisible until the matching objective is built (sceneChangeArea, from the design document)
	auto g1 = std::make_shared<sceneChangeArea>(sf::FloatRect(65 * T + 36.0f, 33 * T - 20.0f, 28.0f, 28.0f), 1, sf::Vector2f(7 * T, 31 * T), "Ferry to Frostgate Island");
	g1->active = false; s.addEntityToLevel(0, g1);
	auto g2 = std::make_shared<sceneChangeArea>(sf::FloatRect(64 * T + 44.0f, 12 * T - 24.0f, 28.0f, 28.0f), 2, sf::Vector2f(7 * T, 31 * T), "Train to Summit Ridge");
	g2->active = false; s.addEntityToLevel(0, g2);

	std::mt19937 rng(1234);
	addBushes(s, 0, rng, 40, 3, 3, 76, 46);
	if (trees) generateTrees(s, 0, rng);
}

// =====================================================================================================================
//  Level 1 - Frostgate Island (reached by the port; small snowy section in the north with the rarer frost trees)
// =====================================================================================================================
static void buildFrostgate(GameScene& s, bool trees)
{
	GameScene::levelState& L = s.levels[1];
	L.name = "Frostgate Island";
	tileMap& m = L.map;
	m.create(60, 40, T_GRASS);
	m.fillRect(0, 0, 60, 2, T_WATER); m.fillRect(0, 38, 60, 2, T_WATER);  // the island is surrounded by water
	m.fillRect(0, 0, 2, 40, T_WATER); m.fillRect(58, 0, 2, 40, T_WATER);
	m.fillRect(2, 2, 56, 14, T_SNOW);                                       // the cold part of the 2nd area
	m.fillRect(24, 30, 12, 5, T_SAND);
	m.fillRect(20, 22, 20, 2, T_PATH);
	m.fillRect(44, 18, 6, 4, T_WATER);
	L.spawn = sf::Vector2f(7 * T, 31 * T);

	auto market = addSell(s, 1, "Harbour Market", 24, 30, 10, 5, sf::Color(0x3d, 0x85, 0xc6));
	for (int t = ITEM_LOG_SPRUCE; t <= ITEM_LOG_FROST; t++) market->setPrice(static_cast<itemType>(t), itemBasePrice(static_cast<itemType>(t)) * 1.15f);
	market->setPrice(ITEM_PLANK, 24.0f);
	market->setPrice(ITEM_CHIP, 5.0f);

	auto back = std::make_shared<sceneChangeArea>(sf::FloatRect(3 * T, 33 * T, 28.0f, 28.0f), 0, sf::Vector2f(68 * T, 34 * T + 10.0f), "Ferry to Cedar Valley");
	s.addEntityToLevel(1, back);
	s.addEntityToLevel(1, std::make_shared<functionalBuilding>(B_CAMPFIRE, 9, 30, 0)); // a fire near the spawn

	std::mt19937 rng(4321);
	addBushes(s, 1, rng, 25, 3, 17, 56, 36);
	if (trees) generateTrees(s, 1, rng);
}

// =====================================================================================================================
//  Level 2 - Summit Ridge (reached by the train; all snow, the airport = final objective)
// =====================================================================================================================
static void buildSummitRidge(GameScene& s, bool trees)
{
	GameScene::levelState& L = s.levels[2];
	L.name = "Summit Ridge";
	tileMap& m = L.map;
	m.create(60, 40, T_SNOW);
	m.fillRect(0, 0, 60, 2, T_HILL); m.fillRect(0, 38, 60, 2, T_HILL);
	m.fillRect(0, 0, 2, 40, T_HILL); m.fillRect(58, 0, 2, 40, T_HILL);
	m.fillRect(40, 20, 6, 5, T_HILL);
	m.fillRect(22, 10, 18, 9, T_SAND); // airport apron
	L.spawn = sf::Vector2f(7 * T, 31 * T);

	auto camp = addSell(s, 2, "Summit Camp", 12, 28, 9, 5, sf::Color(0x3d, 0x85, 0xc6));
	for (int t = ITEM_LOG_SPRUCE; t <= ITEM_LOG_FROST; t++) camp->setPrice(static_cast<itemType>(t), itemBasePrice(static_cast<itemType>(t)) * 1.3f);
	camp->setPrice(ITEM_PLANK, 28.0f);
	camp->setPrice(ITEM_CHIP, 6.0f);

	auto airport = std::make_shared<objectiveBuilding>(2, "Airport", sf::Vector2f(30 * T, 15 * T), sf::Vector2f(96.0f, 64.0f));
	airport->required[ITEM_PLANK] = 40; airport->required[ITEM_LOG_FROST] = 20; airport->required[ITEM_LOG_OAK] = 15; airport->required[ITEM_CHIP] = 20;
	s.addEntityToLevel(2, airport);

	auto back = std::make_shared<sceneChangeArea>(sf::FloatRect(3 * T, 33 * T, 28.0f, 28.0f), 0, sf::Vector2f(64 * T - 10.0f, 17 * T), "Train to Cedar Valley");
	s.addEntityToLevel(2, back);
	s.addEntityToLevel(2, std::make_shared<functionalBuilding>(B_CAMPFIRE, 9, 30, 0));

	std::mt19937 rng(9876);
	addBushes(s, 2, rng, 20, 3, 3, 56, 36);
	if (trees) generateTrees(s, 2, rng);
}

void buildLevel(GameScene& scene, int level, bool generateTreesNow)
{
	scene.levels[level].entities.clear();
	switch (level){
		case 0: buildCedarValley(scene, generateTreesNow); break;
		case 1: buildFrostgate(scene, generateTreesNow); break;
		default: buildSummitRidge(scene, generateTreesNow); break;
	}
}
